insert into public.perfumers (slug, name, country, bio) values
  ('daphne-bugey', 'Daphné Bugey', 'França', 'Mestre perfumista da DSM-Firmenich, formada pelo prestigiado ISIPCA em Versailles. Fascinada pelo universo dos aromas desde a adolescência, Daphné é reconhecida por sua abordagem intuitiva, espírito livre e paixão por viagens e botânica, traduzindo contrastes em acordes cheios de personalidade. É a mente criativa por trás de marcos como Kenzo Amour, Le Labo Rose 31, Jean Paul Gaultier Scandal e D&G K.'),
  ('christophe-raynaud', 'Christophe Raynaud', 'França', 'Mestre perfumista da Givaudan, Christophe Raynaud construiu sua formação olfativa no ISIPCA sob a tutela de lendas do setor. Seu trabalho destaca-se pelo rigor artesanal aliado a uma obsessão por notas luminosas, viciantes e de alto impacto comercial e artístico. Entre seus maiores sucessos mundiais estão Paco Rabanne 1 Million, Mugler Aura e Jean Paul Gaultier Le Beau.'),
  ('nathalie-gracia-cetto', 'Nathalie Gracia-Cetto', 'França', 'Nascida em Grasse e perfumista sênior da Givaudan, Nathalie possui sólida bagagem acadêmica com doutorado em biofísica e biologia molecular. Sua abordagem científica refinada se reflete em construções florais translúcidas e estruturas elegantes de extrema precisão. Assina ícones como Burberry Brit, Burberry Brit Rhythm, Chloé Love, Boucheron Quatre, Tom Ford Soleil Blanc e Jean Paul Gaultier Le Male Le Parfum.'),
  ('fabrice-pellegrin', 'Fabrice Pellegrin', 'França', 'Consagrado Mestre Perfumista da DSM-Firmenich e laureado com o Prix François Coty, Pellegrin é filho de perfumista e herdeiro direto da tradição floral de Grasse. É reconhecido como um dos maiores especialistas da indústria no uso de extratos naturais de alta qualidade e madeiras nobres. Entre suas obras mais aclamadas figuram Diptyque Do Son, Azzaro Wanted e L''Eau d''Issey Pour Homme Solar Lavender.'),
  ('edison-fujita', 'Edison Fujita', 'Brasil', 'Pilar histórico da perfumaria no Brasil, Edison Fujita atuou por décadas em gigantes globais como Drom Fragrances e Givaudan. Teve papel decisivo no desenho da identidade olfativa brasileira entre os anos 1990 e 2010, dominando acordes fougère frescos, aromáticos e florais solares. É o autor de sucessos perenes da Natura, incluindo Kaiak Urbe, Biografia Feminino e Essencial Exclusivo.'),
  ('sonia-constant', 'Sonia Constant', 'França', 'Mestre perfumista da Givaudan e fundadora da casa de alta perfumaria autoral Ella K, Sonia graduou-se pelo ISIPCA e pela escola interna da Givaudan. Sua assinatura artística une poesia visual, acordes etéreos e texturas sedutoras inspiradas em expedições pelo Oriente e África. É a criadora de Tom Ford Noir Pour Femme, Narciso Rodriguez Pure Musc e Valentino Donna Acqua.'),
  ('leonardo-lucheze', 'Leonardo Lucheze', 'Brasil', 'Perfumista sênior com sólida trajetória pela Takasago e atuação destacada no centro de inovação da empresa no Brasil. Lucheze especializou-se em capturar o frescor natural e a intensidade amadeirada demandados pelo consumidor latino-americano, unindo biotecnologia a extratos sustentáveis. Assina fragrâncias de enorme expressão como Natura Homem Sagaz e Kaiak Oceano.'),
  ('alienor-massenet', 'Aliénor Massenet', 'França', 'Perfumista sênior da Symrise com passagens de prestígio pela IFF, Aliénor descende de uma família de artistas e desenvolveu estilo olfativo ousado e iconoclasta. Encontra na sinestesia entre cores, emoções e aromas sua principal força motriz, sendo referência no uso de notas coriáceas e resinosas. É a autora de Maison Margiela Jazz Club e Memo Paris Irish Leather.'),
  ('antoine-maisondieu', 'Antoine Maisondieu', 'França', 'Nascido em Grasse e neto do escritor Albert Camus, Antoine é Mestre Perfumista da Givaudan. Inicialmente direcionado ao direito e à história da arte, descobriu sua vocação na perfumaria clássica, cultivando composições de sofisticação minimalista e apelo contemporâneo. É o autor de sucessos mundiais como Armani Code, Burberry Touch for Men e Comme des Garçons Monocle Scent One: Hinoki.'),
  ('jacques-cavallier', 'Jacques Cavallier-Belletrud', 'França', 'Mestre perfumista exclusivo da Louis Vuitton e lenda viva da indústria olfativa, Cavallier nasceu em Grasse e moldou a história moderna durante suas décadas na Firmenich. Pioneiro no uso inovador de moléculas aquáticas como o Calone, redefiniu tendências globais com clássicos absolutos como Issey Miyake L''Eau d''Issey, Bvlgari Aqua, Lancôme Poême e Giorgio Armani Acqua Di Giò.'),
  ('olivier-cresp', 'Olivier Cresp', 'França', 'Mestre perfumista da DSM-Firmenich, Chevalier des Arts et des Lettres e fundador da Akro, Cresp é oriundo de uma dinastia de comerciantes de matérias-primas de Grasse. Revolucionou para sempre a história da perfumaria ao inventar a família olfativa gourmand com Mugler Angel (1992), assinando também Dolce & Gabbana Light Blue, Cacharel Noa e YSL Black Opium.'),
  ('annick-menardo', 'Annick Menardo', 'França', 'Com formação em química orgânica no ISIPCA e carreira brilhante na Firmenich e Symrise, Annick Menardo é reverenciada pela crítica por seu estilo autoral, assertivo e sem concessões ao óbvio. Destaca-se pelo domínio de acordes contrastantes e notas orientais enigmáticas, tendo concebido obras-primas como Dior Hypnotic Poison, Bvlgari Black, Lolita Lempicka Au Masculin e Boss Bottled.'),
  ('carlos-benaim', 'Carlos Benaïm', 'Marrocos', 'Primeiro perfumista nomeado Master Perfumer na história da IFF e laureado com o Lifetime Achievement Award pela Fragrance Foundation. Formado em engenharia química na França, construiu uma das mais prolíficas carreiras em Nova York, mesclando raízes mediterrâneas ao dinamismo norte-americano. Assina clássicos como Ralph Lauren Polo, Viktor & Rolf Flowerbomb e Frederic Malle Music for a While.'),
  ('napoleao-bastos', 'Napoleão Bastos', 'Brasil', 'Patrimônio vivo da perfumaria brasileira e veterano da IFF, Napoleão Bastos dedicou sua carreira a traduzir a biodiversidade e os gostos do Brasil em formulações de apelo massivo e sofisticado. Fez história ao conceber o processo de maceração em barris de carvalho para o Malbec de O Boticário (2004), o perfume mais vendido da América Latina, além de sucessos para a Natura.'),
  ('pierre-constantin-gueros', 'Pierre-Constantin Guéros', 'França', 'Perfumista sênior da Symrise, com passagens prolongadas por polos criativos em Paris, Nova York e Dubai. Filho de alfaiate parisiense de alta-costura, Guéros transportou a precisão dos tecidos nobres para a composição olfativa, dominando acordes ambarados opulentos e texturas modernas. Entre suas formulações mais célebres estão Carolina Herrera CH Men Privé e Comme des Garçons Odeur 71.'),
  ('jean-christophe-herault', 'Jean-Christophe Hérault', 'França', 'Perfumista sênior da IFF, com formação inspirada pela literatura, arte contemporânea e uma marcante mentoria ao lado de Pierre Bourdon. Seu trabalho equilibra o classicismo francês com construções modernas e magnéticas de alto rastro. Ganhou consagração internacional definitiva como o criador de Creed Aventus, Dolce & Gabbana The One For Men EDP e Mugler Alien Mirage.'),
  ('louise-turner', 'Louise Turner', 'Reino Unido', 'Perfumista sênior da Givaudan, Louise cresceu no interior da Inglaterra rodeada de jardins botânicos, descobrindo cedo sua paixão pelas flores. Reconhecida pela habilidade de capturar a luminosidade e a sensualidade viciante em florais modernos e acordes gourmand, assinou blockbusters mundiais como Carolina Herrera Good Girl, Chloé Love, Mugler Angel Nova e Tom Ford Lost Cherry.'),
  ('florian-gallo', 'Florian Gallo', 'França', 'Perfumista da DSM-Firmenich com atuação destacada entre Paris e a América Latina, Florian combina rigor técnico de laboratório a uma visão cosmopolita e artística da perfumaria fina. Destacou-se no cenário brasileiro por revitalizar o acervo botânico e de nicho de marcas centenárias, sendo responsável por Granado Nostalgia e criações modernas para a linha Egeo de O Boticário.'),
  ('clement-gavarry', 'Clément Gavarry', 'França', 'Nascido em Paris em uma família tradicional de perfumistas de Grasse e radicado em Nova York, Clément é perfumista sênior da DSM-Firmenich, formado pelo ISIPCA. Sua obra é caracterizada por notas almiscaradas sedosas, frescores modernos e forte apelo à cultura pop e de nicho. Criou fenômenos de vendas globais como Ariana Grande Cloud, Tom Ford Black Violet e Prada Amber pour Homme.'),
  ('ane-ayo', 'Ane Ayo', 'Espanha', 'Perfumista sênior da DSM-Firmenich, nascida em Bilbau e com trajetória multicultural entre Espanha, Reino Unido e França. Sua abordagem criativa é profundamente visual e arquitetônica, priorizando transparência, equilíbrio botânico e minimalismo contemporâneo. É a criadora de Issey Miyake A Drop d''Issey, Kenzo Aqua Kenzo Pour Femme e colaboradora em lançamentos de alta gama da Zara e Lalique.'),
  ('john-gamba', 'John Gamba', 'Estados Unidos', 'Perfumista sênior da Givaudan com décadas de liderança técnica nos mercados das Américas. Gamba consolidou reputação de ponta pelo domínio no equilíbrio de estruturas fougère, acordes ozônicos e amadeirados de altíssima performance para a perfumaria fina e mass market, destacando-se em parcerias globais de longa data com Avon (como Avon Luck for Him) e marcas de prestígio.'),
  ('benoist-lapouza', 'Benoist Lapouza', 'França', 'Perfumista sênior da Givaudan com passagens por grandes casas como Drom e Fragrance Resources. Lapouza iniciou sua trajetória artística como violoncelista clássico antes de ingressar na perfumaria sob a mentoria de Pierre Bourdon, transpondo harmonias melódicas para as fórmulas. É o autor da cobiçada obra-prima Angels'' Share da casa By Kilian e de YSL Live Jazz.'),
  ('ralf-schwieger', 'Ralf Schwieger', 'Alemanha', 'Formado em química pela Universidade de Berlim e perfumista sênior da Mane, Schwieger encara a perfumaria como uma ciência rigorosa associada à expressão artística vanguardista. Vencedor do prestigiado Prix François Coty, tem estilo intelectual e refinado, sendo o autor de criações icônicas como Hermès Eau des Merveilles, Frederic Malle Lipstick Rose e Yves Saint Laurent Baby Doll.'),
  ('gabriela-maldonado', 'Gabriela Maldonado', 'Brasil', 'Perfumista brasileira da Symrise com especialização nos principais centros olfativos internacionais da casa na Europa e América Latina. Destaca-se pela precisão técnica na harmonização de notas florais sofisticadas e acordes amadeirados elegantes, tendo participado do desenvolvimento de formulações consagradas do mercado premium nacional, como Elysée Succès de O Boticário.'),
  ('guillaume-flavigny', 'Guillaume Flavigny', 'França', 'Formado pelo ISIPCA e laureado com o cobiçado Prix François Coty para Jovens Perfumistas, Flavigny é perfumista sênior da Givaudan. Apaixonado por teatro e literatura, compõe fragrâncias ricas em contrastes térmicos, unindo transparências aromáticas a fundos orientais opulentos. É o coautor de sucessos internacionais como Elizabeth Arden White Tea e Commodity Velvet.'),
  ('lisa-montes', 'Lisa Montes', 'França', 'Perfumista da Givaudan formada pela Givaudan Perfumery School, Lisa Montes tem se destacado pela sensibilidade estética e forte conexão com o ecossistema brasileiro de fragrâncias. Sua assinatura traduz luminosidade solar, frescores botânicos e texturas aconchegantes e despretensiosas, sendo uma das autoras do aclamado perfume Bossa, da secular casa Granado.'),
  ('leandro-petit', 'Leandro Petit', 'Brasil', 'Perfumista sênior da Givaudan no Brasil, graduado em química e formado na escola de perfumaria da multinacional na França. Petit é um dos narizes mais premiados e dinâmicos da América Latina contemporânea, dominando acordes aquáticos complexos e estruturas gourmand joviais. Entre seus maiores sucessos estão Natura Kaiak Aero, Kaiak Pulso e Egeo Vanilla Vibe de O Boticário.'),
  ('shyamala-maisondieu', 'Shyamala Maisondieu', 'Malásia', 'Nascida na Malásia e perfumista sênior da Givaudan em Paris, Shyamala estudou química no Reino Unido antes de se especializar em Grasse. Suas raízes asiáticas combinadas à escola clássica francesa imprimem às suas criações delicadeza, equilíbrio místico e suntuosidade natural. Assina formulações de prestígio como Tom Ford Velvet Orchid, Etat Libre d''Orange Charogne e Bon Parfumeur 602.'),
  ('hernan-figoli', 'Hernan Fígoli', 'Argentina', 'Nascido em Buenos Aires e perfumista sênior da Givaudan, Fígoli consolidou-se como um dos maiores arquitetos da perfumaria fina na América Latina. Seu trabalho notabiliza-se pelo arrojo em madeiras densas, resinas e acordes aromáticos de grande difusão e apelo masculino marcante. É a mente criativa por trás de campeões de venda como Natura Homem Dom, Homem Essence e Malbec Gold.'),
  ('sophie-truitard', 'Sophie Truitard', 'França', 'Com atuações consistentes por grandes casas da indústria como Drom Fragrances e Givaudan, Sophie Truitard pauta sua estética na sensualidade envolvente e na harmonia de acordes gourmand sofisticados. Desenvolveu estudos aprofundados sobre notas gustativas e florais cremosos, sendo a autora de Coffee Woman Seduction de O Boticário, uma das fragrâncias mais queridas do público brasileiro.'),
  ('veronique-nyberg', 'Véronique Nyberg', 'França', 'Doutora em química orgânica e Vice-Presidente de Criação da Mane, com histórico consolidado na IFF, Véronique alia rigor analítico e paixão por botânica e artes plásticas. Conhecida pela capacidade de criar contrastes vibrantes entre notas sintéticas inovadoras e absolutos florais opulentos, cocriou gigantes do mercado mundial como Paco Rabanne Invictus, Lancôme Trésor In Love e Jimmy Choo Flash.'),
  ('nicolas-beaulieu', 'Nicolas Beaulieu', 'França', 'Formado pelo ISIPCA e perfumista sênior da IFF em Paris, Nicolas é admirado na indústria pelo traço técnico limpo, preciso e de extrema contemporaneidade. Apaixonado por reinventar matérias-primas tradicionais como patchouli e vetiver, assina criações aclamadas pela crítica como Clinique Aromatics in White, Paco Rabanne Invictus Legend, Chloé Nomade Naturelle e Signorina Misteriosa da Ferragamo.'),
  ('marion-costero', 'Marion Costero', 'França', 'Perfumista sênior da Givaudan, formada no prestigiado ISIPCA e estabelecida no Brasil há mais de duas décadas. Costero desempenhou papel pioneiro na tropicalização da alta perfumaria europeia, decodificando a alma da mulher brasileira em estruturas chipre e gourmand inovadoras. Entre seus maiores legados estão o pilar Natura Luna, Natura Ilía Secreto e O Boticário Egeo Choc.'),
  ('jordi-fernandez', 'Jordi Fernández', 'Espanha', 'Mestre perfumista da Givaudan, Jordi é um expoente ímpar por sua trajetória autodidata, impulsionada por profunda paixão pelas paisagens mediterrâneas e pelo fascínio da perfumaria oriental. É internacionalmente consagrado pela habilidade de manipular notas de oud, madeiras nobres e acordes ambarados opulentos, criando Montblanc Explorer Platinum e Ex Nihilo The Hedonist.'),
  ('claudio-de-deus', 'Cláudio de Deus', 'Brasil', 'Verdadeira lenda e patriarca da perfumaria nacional na Givaudan, Cláudio de Deus dedicou mais de quatro décadas ao desenvolvimento de essências memoráveis no país. Foi um dos pioneiros a trabalhar com acordes frescos adaptados ao clima tropical brasileiro, definindo gerações inteiras por meio de clássicos absolutos como Natura Biografia Masculino, Biografia Feminino e Natura Kaiak Aventura.'),
  ('yves-cassar', 'Yves Cassar', 'Argélia', 'Nascido no Norte da África e Master Perfumer da IFF em Nova York, Yves Cassar graduou-se em química em Paris antes de ingressar no universo olfativo. Seu apreço quase botânico pelas matérias-primas naturais nobres e processos de extração artesanais rendeu criações de elegância impecável, assinando Tom Ford for Men, Calvin Klein Crave e colaborações de peso com Estée Lauder.'),
  ('thierry-bessard', 'Thierry Bessard', 'França', 'Perfumista sênior da DSM-Firmenich com vasta trajetória internacional e atuação marcante na consolidação do mercado de perfumaria fina na América do Sul. Mestre em traduzir o requinte e a complexidade das notas amadeiradas e florais clássicas da escola francesa para os mercados tropicais, formulou fragrâncias de destaque para marcas de prestígio como Phebo, Natura e O Boticário.'),
  ('veronica-casanova', 'Verônica Casanova', 'Brasil', 'Perfumista sênior da Symrise, Verônica é uma das principais vozes femininas da perfumaria técnica e criativa na América Latina. Desenvolveu sólida carreira formulando estruturas florais modernas, chipres luminosos e acordes frutados com alta fixação. É coautora de grandes sucessos para a Natura, destacando-se na assinatura sofisticada de fragrâncias como Luna Radiante.'),
  ('luciana-bergamasco', 'Luciana Bergamasco', 'Brasil', 'Perfumista da Givaudan baseada em São Paulo, Luciana especializou-se em captar tendências olfativas jovens, cosméticas e energizantes para a perfumaria fina e de cuidados pessoais. Detém técnica refinada na composição de florais brancos e acordes frutados gourmand, desenvolvendo criações de destaque para gigantes nacionais como Eudora, Quem Disse, Berenice? e O Boticário.'),
  ('roberth-sertorio', 'Roberth Sertório', 'Brasil', 'Perfumista sênior da Symrise no Brasil, Roberth Sertório distingue-se na indústria pela excelência técnica em estruturas masculinas robustas, amadeiradas de longa projeção e acordes especiados quentes. É o criador de sucessos expressivos da perfumaria nacional de prestígio, com papel fundamental em lançamentos icônicos como O Boticário Malbec Flame e Zaad Expedition.'),
  ('alfredo-monteiro-filho', 'Alfredo Monteiro Filho', 'Brasil', 'Considerado o grande pioneiro da perfumaria moderna no Brasil, Monteiro Filho atuou como perfumista-chefe da IFF por décadas, fundando as bases da memória olfativa de gerações no país. Foi o criador visionário do clássico Acqua Fresca (1979) e do floral juvenil Thaty (1980), as duas primeiras fragrâncias que transformaram O Boticário em uma potência global.'),
  ('jacques-huclier', 'Jacques Huclier', 'França', 'Mestre perfumista da Givaudan, Huclier formou-se no prestigiado ISIPCA e construiu uma das mais inovadoras trajetórias da perfumaria moderna entre Paris e Nova York. Célebre pelo desassombro criativo e por construir contrastes radicais de alto impacto, concebeu o lendário Thierry Mugler A*Men (1996), além de assinar sucessos das linhas Gucci Guilty Pour Homme e Nina Ricci.')
insert into public.perfume_perfumers (perfume_id, perfumer_id, position)
