-- Perfil de 42 perfumistas (país e bio em pt-BR) a partir de scripts/catalog-data/perfumers-profile.json.
-- Upsert por `slug`: linhas novas entram; as existentes (criadas pelo backfill ou por migrations
-- anteriores) recebem só `country` e `bio`, sem mexer no `name`. As ligações em `perfume_perfumers`
-- NÃO entram aqui: só com a autoria confirmada na página da marca ou da casa de fragrância.

on conflict (slug) do update
  set country = excluded.country,
      bio = excluded.bio;

-- Mesclagem: "Nathalie Cetto" (slug nathalie-cetto, criada pelo backfill e pela ingestão do lote
-- jpg) é a mesma pessoa de "Nathalie Gracia-Cetto". Reaponta as ligações para o slug mantido e
-- apaga a duplicata. Se a duplicata não existir, nada acontece.
select pp.perfume_id, keep.id, pp.position
from public.perfume_perfumers pp
join public.perfumers dup on dup.id = pp.perfumer_id and dup.slug = 'nathalie-cetto'
cross join (select id from public.perfumers where slug = 'nathalie-gracia-cetto') keep
on conflict (perfume_id, perfumer_id) do nothing;

delete from public.perfumers where slug = 'nathalie-cetto';
